end">@if(! $paymentRequest && $batch->status === 'VERIFIED' && auth()->user()->hasPermission('finance.commission-payouts.create'))<button class="btn btn-sm btn-dark js-create-request" data-recipient-id="{{ $total['id'] }}">สร้างใบขอจ่าย</button>@else — @endif</td></tr>@empty<tr><td colspan="6" class="text-center text-secondary py-4">ไม่พบรายการคอมมิชชั่น</td></tr>@endforelse</tbody><tfoot><tr><th colspan="2" class="text-end">รวม</th><th class="text-end">{{ number_format((float) $batch->total_amount, 2) }}</th><th colspan="3"></th></tr></tfoot></table></div></div></div><div class="card border-0 shadow-sm"><div class="card-body p-3 p-lg-4"><h2 class="h6 mb-3">ประวัติเอกสาร</h2>@forelse($history as $event)<div class="d-flex gap-3 border-bottom py-2"><div class="small text-secondary text-nowrap">{{ $event->created_at?->format('d/m/Y H:i') }}</div><div><strong>{{ $event->action }}</strong><div class="small text-secondary">{{ $event->user?->name ?? 'ระบบ' }}</div>@if($event->reason)<div class="small mt-1"><span class="text-secondary">เหตุผล:</span> {{ $event->reason }}</div>@endif</div></div>@empty<p class="text-secondary mb-0">ยังไม่มีประวัติเอกสาร</p>@endforelse</div></div>
