@push('scripts')<script>$(function(){$.ajaxSetup({headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content'),'Accept':'application/json'}});const fail=x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'ไม่สามารถดำเนินการได้'});$('.js-verify').on('click',function(){const b=$(this);Swal.fire({icon:'question',text:'ยืนยันว่าตรวจสอบยอดทั้งชุดครบถ้วนแล้ว?',showCancelButton:true,confirmButtonText:'ตรวจสอบแล้ว',cancelButtonText:'ย้อนกลับ'}).then(r=>{if(r.isConfirmed)$.post(b.data('url'),{},x=>location.href=x.redirect).fail(fail);});});$('.js-cancel').on('click',function(){const b=$(this);Swal.fire({icon:'warning',title:'ยกเลิกเอกสาร?',input:'text',inputValidator:v=>!v?'กรุณาระบุเหตุผล':undefined,showCancelButton:true,confirmButtonText:'ยกเลิกเอกสาร'}).then(r=>{if(r.isConfirmed)$.post(b.data('url'),{reason:r.value},x=>location.href=x.redirect).fail(fail);});});$('.js-create-request').on('click',function(){const b=$(this).prop('disabled',true);$.post('{{ route('finance.commission-payouts.requests.store', $batch) }}',{recipient_user_id:b.data('recipient-id')},x=>location.href=x.redirect).fail(fail).always(()=>b.prop('disabled',false));});$('.js-bulk-action').on('click',function(){const b=$(this);const send=reason=>{b.prop('disabled',true);$.post(b.data('url'),reason?{reason:reason}:{},x=>location.href=x.redirect).fail(fail).always(()=>b.prop('disabled',false));};if(b.data('reason')){Swal.fire({icon:'warning',title:'ยกเลิกใบขอจ่ายทั้งชุด?',input:'text',inputValidator:v=>!v?'กรุณาระบุเหตุผล':undefined,showCancelButton:true,confirmButtonText:'ยกเลิกเอกสาร'}).then(r=>{if(r.isConfirmed)send(r.value);});}else{Swal.fire({icon:'question',text:b.data('confirm'),showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'ย้อนกลับ'}).then(r=>{if(r.isConfirmed)send();});}});});</script>@endpush
